import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("documents cannot be added to a vendor under review", { tag: "@DOC-06" }, async ({ apiAs }) => {
  // Arrange: a draft vendor with every required document uploaded and extracted, then submitted
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Doc Lock"), category: "logistics", contact_email: "ops@acme.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  const required = [
    ["w9", "w9.txt"],
    ["insurance_certificate", "insurance_certificate.txt"],
    ["contract", "contract.txt"],
  ] as const;
  for (const [kind, file] of required) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  // Extraction runs in the background; submit only sees extracted documents.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await res.json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 30_000 },
    )
    .toBe(true);

  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submit.status(), await submit.text()).toBe(200);
  expect((await submit.json()).status, await submit.text()).toBe("in_review");

  // Act: try to add another document while under review
  const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
    },
  });

  // Assert
  const body = await response.text();
  expect(response.status(), body).toBe(409);
  expect(JSON.parse(body).error.code, body).toBe("vendor_locked");
});
